messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: bfd/coff-arm.c
Line: 2090
Function: bfd_arm_process_before_allocation
Bug type: out-of-bounds-read
CWE: CWE-125
Explanation: Uses obj_coff_sym_hashes(abfd)[symndx] without validating that symndx is non-negative. Values < -1 (malformed reloc r_symndx) bypass the -1 check and lead to indexing the array with a negative index, causing an out-of-bounds read.

Source context:
```c
     2050:   sec = abfd->sections;
     2051: 
     2052:   if (sec == NULL)
     2053:     return true;
     2054: 
     2055:   for (; sec != NULL; sec = sec->next)
     2056:     {
     2057:       struct internal_reloc * i;
     2058:       struct internal_reloc * rel;
     2059: 
     2060:       if (sec->reloc_count == 0)
     2061: 	continue;
     2062: 
     2063:       /* Load the relocs.  */
     2064:       /* FIXME: there may be a storage leak here.  */
     2065:       i = bfd_coff_read_internal_relocs (abfd, sec, true, NULL, false, NULL);
     2066: 
     2067:       BFD_ASSERT (i != 0);
     2068: 
     2069:       for (rel = i; rel < i + sec->reloc_count; ++rel)
     2070: 	{
     2071: 	  unsigned short		 r_type	 = rel->r_type;
     2072: 	  long				 symndx;
     2073: 	  struct coff_link_hash_entry *	 h;
     2074: 
     2075: 	  symndx = rel->r_symndx;
     2076: 
     2077: 	  /* If the relocation is not against a symbol it cannot concern us.  */
     2078: 	  if (symndx == -1)
     2079: 	    continue;
     2080: 
     2081: 	  /* If the index is outside of the range of our table, something has gone wrong.  */
     2082: 	  if (symndx >= obj_conv_table_size (abfd))
     2083: 	    {
     2084: 	      /* xgettext:c-format */
     2085: 	      _bfd_error_handler (_("%pB: illegal symbol index in reloc: %ld"),
     2086: 				  abfd, symndx);
     2087: 	      continue;
     2088: 	    }
     2089: 
>>>  2090: 	  h = obj_coff_sym_hashes (abfd)[symndx];
     2091: 
     2092: 	  /* If the relocation is against a static symbol it must be within
     2093: 	     the current section and so cannot be a cross ARM/Thumb relocation.  */
     2094: 	  if (h == NULL)
     2095: 	    continue;
     2096: 
     2097: 	  switch (r_type)
     2098: 	    {
     2099: 	    case ARM_26:
     2100: 	      /* This one is a call from arm code.  We need to look up
     2101: 		 the target of the call. If it is a thumb target, we
     2102: 		 insert glue.  */
     2103: 
     2104: 	      if (h->symbol_class == C_THUMBEXTFUNC)
     2105: 		record_arm_to_thumb_glue (info, h);
     2106: 	      break;
     2107: 
     2108: #ifndef ARM_WINCE
     2109: 	    case ARM_THUMB23:
     2110: 	      /* This one is a call from thumb code.  We used to look
     2111: 		 for ARM_THUMB9 and ARM_THUMB12 as well.  We need to look
     2112: 		 up the target of the call. If it is an arm target, we
     2113: 		 insert glue.  If the symbol does not exist it will be
     2114: 		 given a class of C_EXT and so we will generate a stub
     2115: 		 for it.  This is not really a problem, since the link
     2116: 		 is doomed anyway.  */
     2117: 
     2118: 	      switch (h->symbol_class)
     2119: 		{
     2120: 		case C_EXT:
     2121: 		case C_STAT:
     2122: 		case C_LABEL:
     2123: 		  record_thumb_to_arm_glue (info, h);
     2124: 		  break;
     2125: 		default:
     2126: 		  ;
     2127: 		}
     2128: 	      break;
     2129: #endif
     2130: 
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/binutils_upstream reproducer.c -L/tmp/binutils_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/binutils_upstream
